def bestand_zuordnen(apps, schema_editor):
    verbindung = schema_editor.connection.alias
    Dokument = apps.get_model("kern", "Dokument")
    Bereich = apps.get_model("kern", "Wissensbereich")
    Regel = apps.get_model("kern", "Zugangsregel")
    Nutzer = apps.get_model("kern", "Nutzer")
    Beschluss = apps.get_model("kern", "Beschluss")
    Fach = apps.get_model("fachdaten", "Fach")
    redaktion = list(Nutzer.objects.using(verbindung).filter(groups__name="Redaktion").distinct())
    for dokument in Dokument.objects.using(verbindung).all():
        if dokument.fach:
            bereich, _ = Bereich.objects.using(verbindung).get_or_create(
                schluessel=f"fach-{dokument.fach}",
                defaults={
                    "name": Fach.objects.using(verbindung)
                    .filter(schluessel=dokument.fach)
                    .values_list("name", flat=True)
                    .first()
                    or dokument.fach.capitalize()
                },
            )
            Dokument.objects.using(verbindung).filter(pk=dokument.pk).update(bereich=bereich)
        # Bestehende Personen behalten ihre bisherigen redaktionellen Bereiche.
        # Neue Rollenmitglieder erben dadurch keine pauschalen globalen Rechte.
        for nutzer in redaktion:
            Regel.objects.using(verbindung).get_or_create(
                dokument=dokument, nutzer=nutzer, defaults={"bearbeiten": True}
            )
    for beschluss in Beschluss.objects.using(verbindung).all():
        ids = set(beschluss.beschlossene_versionen.values_list("eintrag__dokument_id", flat=True))
        if beschluss.protokoll_eintrag_id:
            ids.add(beschluss.protokoll_eintrag.dokument_id)
        if beschluss.protokoll_anhang_id:
            anhang = beschluss.protokoll_anhang
            if anhang.dokument_id:
                ids.add(anhang.dokument_id)
            if anhang.eintrag_id:
                ids.add(anhang.eintrag.dokument_id)
        beschluss.dokumente.add(*ids)


